import "../../styles/index-base.css";
import "../../styles/components/number-field.css";
import { NumberField as NumberFieldPrimitive } from "@base-ui/react/number-field";
import { Minus, Plus } from "@phosphor-icons/react";
import { useId, type ReactNode } from "react";
import { cn } from "../../lib/cn";

export type NumberFieldProps = Omit<NumberFieldPrimitive.Root.Props, "children" | "className" | "id"> & {
  id?: string;
  label?: string;
  description?: string;
  error?: string;
  suffix?: ReactNode;
  className?: string;
  inputClassName?: string;
  inputProps?: Omit<NumberFieldPrimitive.Input.Props, "id" | "className" | "aria-describedby" | "aria-invalid">;
};

export function NumberField({
  id: providedId,
  label,
  description,
  error,
  suffix,
  className,
  inputClassName,
  inputProps,
  ...props
}: NumberFieldProps) {
  const generatedId = useId();
  const id = providedId ?? generatedId;
  const descriptionId = description ? `${id}-description` : undefined;
  const errorId = error ? `${id}-error` : undefined;
  const describedBy = [descriptionId, errorId].filter(Boolean).join(" ") || undefined;
  const accessibleLabel = label ?? inputProps?.["aria-label"] ?? "Value";

  return (
    <NumberFieldPrimitive.Root id={id} className={cn("ix-number-field", className)} data-invalid={Boolean(error) || undefined} {...props}>
      {label && <label className="ix-field__label" htmlFor={id}>{label}</label>}
      <NumberFieldPrimitive.Group className="ix-number-field__group">
        <NumberFieldPrimitive.Decrement className="ix-number-field__step" aria-label={`Decrease ${accessibleLabel}`}><Minus /></NumberFieldPrimitive.Decrement>
        <NumberFieldPrimitive.Input id={id} className={cn("ix-number-field__input", inputClassName)} aria-invalid={Boolean(error) || undefined} aria-describedby={describedBy} {...inputProps} />
        {suffix && <span className="ix-number-field__suffix" aria-hidden="true">{suffix}</span>}
        <NumberFieldPrimitive.Increment className="ix-number-field__step" aria-label={`Increase ${accessibleLabel}`}><Plus /></NumberFieldPrimitive.Increment>
      </NumberFieldPrimitive.Group>
      {description && <div id={descriptionId} className="ix-field__description">{description}</div>}
      {error && <div id={errorId} className="ix-field__error">{error}</div>}
    </NumberFieldPrimitive.Root>
  );
}

/* Generated from src/styles.css. Do not edit directly. */

@layer index.tokens, index.base, index.components;

@layer index.components {
.ix-field__label { color: var(--ix-ink); font-size: 12px; font-weight: 550; }

.ix-field__description,
.ix-field__error { color: var(--ix-ink-tertiary); font-size: 11.5px; line-height: 1.45; }

.ix-field__error { color: var(--ix-fg-default); font-weight: 520; }

:root[data-theme="dark"] .ix-field__error { color: var(--ix-ink); }

.ix-number-field { display: grid; min-width: 0; gap: 6px; }

.ix-number-field__group {
  display: flex;
  width: 100%;
  min-width: 0;
  height: 32px;
  align-items: center;
  overflow: hidden;
  border: 1px solid var(--ix-control-border);
  border-radius: var(--ix-radius-sm);
  background: var(--ix-bg-control);
  box-shadow: var(--ix-shadow-control);
  transition: border-color var(--ix-hover-duration), box-shadow var(--ix-hover-duration);
}

.ix-number-field__group:focus-within { border-color: var(--ix-control-border-hover); box-shadow: 0 0 0 2px var(--ix-focus-control); }

.ix-number-field__input { width: 100%; min-width: 0; height: 100%; padding: 0 6px; border: 0; outline: 0; background: transparent; color: var(--ix-fg-default); font-size: var(--ix-type-ui); font-variant-numeric: tabular-nums; }

.ix-number-field__input::placeholder { color: var(--ix-fg-subtle); }

.ix-number-field__step { display: grid; width: 30px; height: 30px; flex: 0 0 30px; padding: 0; place-items: center; border: 0; background: transparent; color: var(--ix-fg-muted); cursor: pointer; transition: color var(--ix-hover-duration), background-color var(--ix-hover-duration), transform var(--ix-press-duration) var(--ix-ease-out); }

.ix-number-field__step svg { width: 12px; height: 12px; }

.ix-number-field__step:focus-visible { z-index: 1; outline: 2px solid var(--ix-focus-control); outline-offset: -2px; }

.ix-number-field__step:active { transform: scale(.9); }

.ix-number-field__step[data-disabled] { color: var(--ix-fg-disabled); cursor: not-allowed; }

.ix-number-field__suffix { padding-right: 4px; color: var(--ix-fg-subtle); font-size: var(--ix-type-label); }

.ix-number-field[data-disabled] .ix-number-field__group { background: var(--ix-bg-subtle); box-shadow: none; }

.ix-number-field[data-disabled] .ix-number-field__input { color: var(--ix-fg-disabled); cursor: not-allowed; }

.ix-number-field[data-invalid] .ix-number-field__group { box-shadow: inset 2px 0 0 var(--ix-fg-default); }

@media (hover: hover) and (pointer: fine) {
.ix-number-field__step:not([data-disabled]):hover { background: var(--ix-hover); color: var(--ix-fg-default); }
}

@media (prefers-reduced-motion: reduce) {
.ix-number-field__step:active { transform: none; }
}
}
